mapper.sql:
WHERE e.is_system = 0
  AND e.company_id = #{companyId}
  AND e.deleted_at IS NULL

      AND e.resigned_at IS NOT NULL
      AND e.resigned_at IS NULL


      AND (e.name LIKE CONCAT('%', #{keyword}, '%')
           OR e.user_id LIKE CONCAT('%', #{keyword}, '%'))

  AND e.department_id = #{departmentId}
  AND a.role = #{role}
  AND a.status = #{accountStatus}
  AND a.must_change_password = #{mustChangePassword}
